(()=>{
const section=document.createElement('section');section.className='card';section.id='purchase';section.style.margin='28px 0';
const content={zh:{prices:['¥19.00','¥49.00','¥149.00'],title:'按需购买，不自动续费',intro:'额度包价格草案 · 收款尚未启用',names:['轻量包','常用包','进阶包'],units:['50,000 计费字符','150,000 计费字符','500,000 计费字符'],docs:['最多 1 份短文档','最多 3 份短文档','最多 10 份短文档'],button:'购买',note:'每份 DOCX、PPTX、PDF 最低消耗 50,000 计费字符，长文档按实际计费量消耗。额度有效期将在正式销售前公布。人民币价格为独立定价草案，并非实时汇率换算；税费与最终结算金额将在付款前明确。',payments:'支付接入计划：支付宝、微信支付、PayPal（均待开通，暂不支持付款）。',compare:'参考：你提供的美国区 DeepL Individual 年付折合 $8.74/月，每年支付 $104.88，含每月3份文档翻译及其他功能。本站 ¥49.00 额度包最多支持3份各不超过50,000计费字符的文档；额度、功能与账期不同，不代表同等服务更便宜。'},en:{prices:['$2.49','$6.49','$19.99'],title:'Buy credits when you need them',intro:'Draft credit packs · Payments are not enabled',names:['Light','Everyday','Plus'],units:['50,000 billable characters','150,000 billable characters','500,000 billable characters'],docs:['Up to 1 short document','Up to 3 short documents','Up to 10 short documents'],button:'Buy now',note:'Each DOCX, PPTX or PDF uses at least 50,000 billable characters. Longer documents use their actual billed amount. Credit validity will be announced before sales open. USD prices are provisional; taxes and the final total will be shown before payment.',payments:'Planned payments: Alipay, WeChat Pay and PayPal (all pending merchant activation; payments unavailable).',compare:'Reference: The supplied US DeepL Individual annual offer is $8.74/month, billed $104.88/year, with 3 file translations per month and other features. Our $6.49 pack covers at most 3 documents of up to 50,000 billable characters each. Allowances, features and billing terms differ; this is not a like-for-like savings claim.'}};
function render(){const c=content[document.documentElement.lang==='en'?'en':'zh'];section.replaceChildren();const title=document.createElement('h2');title.textContent=c.title;section.append(title);const intro=document.createElement('p');intro.className='muted';intro.textContent=c.intro;section.append(intro);const grid=document.createElement('div');grid.style.cssText='display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:16px';c.prices.forEach((price,i)=>{const card=document.createElement('div');card.style.cssText='border:1px solid #e0e6ef;border-radius:12px;padding:20px';for(const [tag,text] of [['h3',c.names[i]],['h2',price],['p',c.units[i]],['p',c.docs[i]]]){const el=document.createElement(tag);el.textContent=text;card.append(el)}const button=document.createElement('button');button.onclick=()=>{location.href="order.html?plan="+i+"&lang="+(document.documentElement.lang==="en"?"en":"zh")};button.textContent=c.button;button.style.width='100%';card.append(button);grid.append(card)});section.append(grid);for(const text of [c.note]){const p=document.createElement('p');p.className='muted';p.style.lineHeight='1.8';p.textContent=text;section.append(p)}}
document.querySelector('main').append(section);render();new MutationObserver(render).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
})();



